const inc = $input.item.json;
const body = { phone: inc.telefone };

// Campos cadastrais (sem validacao, entram como vierem)
const campos = [
  "email",
  "site",
  "cidade",
  "uf",
  "cargo",
  "cnpj_empresa",
  "cidade_de_atuacao",
  "estado_de_atuacao",
  "obs"
];
for (const c of campos) {
  if (inc[c] && inc[c].toString().trim() !== "") body[c] = inc[c].toString().trim();
}

// Status: so aceita valor da lista branca, normalizado
const STATUS_VALIDOS = [
  "em atendimento",
  "retrabalharnofuturo",
  "naoeoICP",
  "encaminhar parcerias"
];
if (inc.status_plano_acao && inc.status_plano_acao.toString().trim() !== "") {
  const bruto = inc.status_plano_acao.toString().trim();
  const match = STATUS_VALIDOS.find(s => s.toLowerCase() === bruto.toLowerCase());
  if (match) {
    body.status_plano_acao = match;
  } else {
    throw new Error(`status_plano_acao invalido: "${bruto}". Validos: ${STATUS_VALIDOS.join(", ")}`);
  }
}

// fup: so YYYY-MM-DD, e so faz sentido com retrabalharnofuturo
if (inc.fup && inc.fup.toString().trim() !== "") {
  const fup = inc.fup.toString().trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fup)) {
    throw new Error(`fup invalido: "${fup}". Formato esperado YYYY-MM-DD.`);
  }
  body.fup = fup;
}
if (body.status_plano_acao === "retrabalharnofuturo" && !body.fup) {
  throw new Error("status retrabalharnofuturo exige o campo fup (YYYY-MM-DD).");
}

// obs obrigatorio nos status terminais
const EXIGEM_OBS = ["naoeoICP", "encaminhar parcerias"];
if (EXIGEM_OBS.includes(body.status_plano_acao) && !body.obs) {
  throw new Error(`status ${body.status_plano_acao} exige o campo obs preenchido.`);
}

return { json: { body } };

